// misaki.js
// Event functions of おくり島. Load this after avg.js in each scene's HTML.
// (generated by scenario/misaki/game/write.js)

const PERSON_IMG_CLASS = 'img-person1';

// overlay a person's image on the scene image (img/person-<name>.png)
const showPersonImage = function (name) {
	$('#image-area .' + PERSON_IMG_CLASS).remove();
	$('#image-area').append($('<img>', { src: '../img/person-' + name + '.png', addClass: PERSON_IMG_CLASS }));
};
const hidePersonImage = function () {
	$('#image-area .' + PERSON_IMG_CLASS).remove();
};

// show the person and switch to person mode
const showPerson = function (name) {
	const cur = $('#image-area .' + PERSON_IMG_CLASS).attr('src') || '';
	// keep a picture of this same person (an expression); no slash in the test: the static build rewrites quoted paths
	if (cur.indexOf('person-' + name + '-') < 0) showPersonImage(name);
	setPersonMode(name);
	getCommands(getSceneId());
	return true;
};
["yukari","mio","soichiro","shino","tatsuo","sawako","kuroki","jinpachi","osawa","tome","kenta","kiyo","sendo"].forEach(function (name) {
	const cap = name.split('-').map(function (w) { return w[0].toUpperCase() + w.slice(1); }).join('');
	sceneEvents['show' + cap] = function () { return showPerson(name); };
	// talking to the person without a picture of them
	sceneEvents['talk' + cap] = function () { hidePersonImage(); setPersonMode(name); getCommands(getSceneId()); return true; };
	sceneEvents['img' + cap] = function () { showPersonImage(name); return true; };
});
// pictures that only replace the image (an expression, other clothes)
["osawa-troubled","kenta-worried","mio-smile","mio-yukata","shino-cold","tatsuo-night","kiyo-smile","yukari-serious"].forEach(function (name) {
	const cap = name.split('-').map(function (w) { return w[0].toUpperCase() + w.slice(1); }).join('');
	sceneEvents['img' + cap] = function () { showPersonImage(name); return true; };
});

// a command whose choices answer a question: show the question (message Q00) instead of the common one
const QUESTION_COMMANDS = ['AC1', 'AC2', 'AC3'];
document.addEventListener('click', function (e) {
	const li = e.target.closest && e.target.closest('#command-list li');
	if (!li || QUESTION_COMMANDS.indexOf(li.id) < 0) return;
	e.stopImmediatePropagation();
	e.preventDefault();
	if (!isOk) return;
	isOk = false;
	const sceneId = getSceneId();
	const flag = getFlag();
	execAjax('../api/message', { sceneId: sceneId, commandId: li.id, targetId: 'Q00', flag: flag }, function (q) {
		execAjax('../api/target', { sceneId: sceneId, commandId: li.id, flag: flag }, function (data) {
			// no question for this flag (the engine answers 'ERROR: No message!'): the command's usual message
			const ask = q && q.message && q.message.indexOf('^') < 0 && q.message.indexOf('ERROR:') !== 0 ? q.message : data.message;
			if ((data.commands || []).length > 0) showCommands({ message: ask, commands: data.commands });
			else showMessage(data);
		});
	});
}, true);

/* --------------------------------------------------
* people of a scene
*   話す (TKX): the people here. One person: a one-click 「〜と話す」
*   ほかの人と話す (SWX): the others, while talking to someone. One other: a one-click 「〜と話す」
* -------------------------------------------------- */
const SCENE_PEOPLE = {"00001":{"P00":"yukari"},"00002":{"P00":"sendo","P01":"yukari"},"00003":{"P00":"kenta","P01":"tatsuo","P02":"kuroki"},"00004":{"P00":"tome","P02":"yukari"},"00024":{"P00":"kuroki"},"00005":{"P00":"soichiro"},"00048":{"P00":"kiyo"},"00006":{"P00":"shino","P01":"sawako"},"00007":{"P00":"mio"},"00008":{"P00":"yukari"},"00009":{"P00":"osawa"},"00011":{"P00":"kenta"},"00012":{"P00":"osawa"},"00013":{"P00":"kenta"},"00014":{"P00":"yukari","P01":"tome"},"00016":{"P00":"shino","P01":"sawako"},"00017":{"P00":"soichiro"},"00049":{"P00":"kiyo"},"00018":{"P00":"jinpachi"},"00029":{"P00":"mio"},"00020":{"P00":"osawa","P01":"yukari"},"00021":{"P00":"mio"},"00023":{"P00":"kiyo"},"00030":{"P00":"osawa"},"00031":{"P00":"osawa"},"00032":{"P00":"osawa"},"00033":{"P00":"kenta"},"00034":{"P00":"yukari","P01":"tome"},"00035":{"P00":"shino","P01":"sawako"},"00036":{"P00":"soichiro"},"00062":{"P00":"kiyo"},"00072":{"P00":"mio"},"00043":{"P00":"soichiro"},"00077":{"P00":"kenta"},"00053":{"P00":"yukari","P01":"tome"},"00054":{"P00":"osawa"},"00055":{"P00":"osawa"},"00056":{"P00":"shino","P01":"sawako"},"00059":{"P00":"kiyo"},"00061":{"P00":"jinpachi"}};
// the targets of TKX / SWX the player can choose now (SWX leaves out the person already talked to)
const peopleTargets = function (commandId, commands) {
	const here = SCENE_PEOPLE[getSceneId()] || {};
	return (commands || []).filter(function (t) {
		return !(commandId === 'SWX' && here[t.targetId] === getPersonMode());
	});
};
const PEOPLE_COMMANDS = ['TKX', 'SWX'];
// 話を切り上げる, and 考える when there is only one thing to think about, run at once (no list of one)
const DIRECT_COMMANDS = ['END', 'THK'];
document.addEventListener('click', function (e) {
	const li = e.target.closest && e.target.closest('#command-list li');
	if (!li) return;
	const people = PEOPLE_COMMANDS.indexOf(li.id) >= 0;
	if (!people && DIRECT_COMMANDS.indexOf(li.id) < 0) return;
	e.stopImmediatePropagation();
	e.preventDefault();
	if (!isOk) return;
	isOk = false;
	const sceneId = getSceneId();
	const flag = getFlag();
	execAjax('../api/target', { sceneId: sceneId, commandId: li.id, flag: flag }, function (data) {
		const ts = people ? peopleTargets(li.id, data.commands) : (data.commands || []);
		if (ts.length === 1) {
			getMessage(sceneId, li.id, ts[0].targetId, flag);
			getCommands(sceneId);
		} else if (ts.length > 1) {
			showCommands({ message: data.message, commands: ts });
		} else {
			showMessage(data);
		}
	});
}, true);
// a scene's music and tint can depend on the flags: decided on window's capture phase, before bgm.js starts the music
const SCENE_BY = {"00027":[["2882304260152754177",{"img":"bg-mikage-house-evening"}]],"00016":[["150307867894743042",{"cls":"dusk"}]],"00030":[["274877906948",{"bgm":"unrest"}],["262148",{"bgm":"aftermath"}]],"00031":[["262148",{"bgm":"aftermath"}]],"00054":[["36165222408",{"bgm":"unrest","img":"bg-chuzaisho"}]]};
window.addEventListener('DOMContentLoaded', function () {
	const rows = SCENE_BY[getSceneId()];
	if (!rows) return;
	const flag = BigInt(getFlag() || 0);
	rows.forEach(function (row) {
		const need = BigInt(row[0]);
		if ((flag & need) !== need) return;
		const audio = document.getElementById('bgm-audio');
		if (row[1].bgm && audio) {
			audio.dataset.track = row[1].bgm;
			audio.src = '../audio/bgm-' + row[1].bgm + '.mp3';
		}
		if (row[1].cls) document.body.classList.add(row[1].cls);
		// another picture for the scene (e.g. the same place at dusk); no slash-led path: the static build rewrites those
		if (row[1].img) { const base = document.querySelector('#image-area img.img-base'); if (base) base.src = '../img/' + row[1].img + '.png'; }
	});
}, true);
// 話す / ほかの人と話す are hidden when there is nobody, and name the person when there is one
// in a quiz scene (答える) nothing but the answer is offered
const QUIZ_SCENES = ["00051"];
$(function () {
	const list = document.getElementById('command-list');
	if (!list) return;
	new MutationObserver(function () {
		PEOPLE_COMMANDS.forEach(function (id) {
			const li = document.getElementById(id);
			if (!li || li.dataset.checked) return;
			li.dataset.checked = '1';
			execAjax('../api/target', { sceneId: getSceneId(), commandId: id, flag: getFlag() }, function (data) {
				const ts = peopleTargets(id, data.commands);
				if (ts.length === 0) $(li).remove();
				else if (ts.length === 1) $(li).text(ts[0].text);
			});
		});
	}).observe(list, { childList: true });
});

