/* --------------------------------------------------
* screen effects (quiet ones)
* -------------------------------------------------- */
sceneEvents.fadeOut = function () { $('<div class="fx-black"></div>').appendTo('#image-area'); return true; };
// the music fades out with the picture (the long fade at the end of the ミサキ送り)
const fadeAudio = function (a, ms) {
	if (!a) return;
	const v0 = a.volume, t0 = Date.now();
	const id = setInterval(function () {
		const k = Math.min(1, (Date.now() - t0) / ms);
		a.volume = v0 * (1 - k);
		if (k >= 1) clearInterval(id);
	}, 50);
};
sceneEvents.fadeOutSlow = function () {
	$('<div class="fx-black fx-slow"></div>').appendTo('#image-area');
	fadeAudio(document.getElementById('bgm-audio'), 5000);
	fadeAudio(overlay, 5000);
	return true;
};
sceneEvents.fadeOutLong = function () { $('<div class="fx-black fx-long"></div>').appendTo('#image-area'); return true; };
sceneEvents.fadeIn = function () { $('#image-area .fx-black').remove(); return true; };
// a power cut: the picture goes dark at once, and comes back by candlelight
sceneEvents.lightsOut = function () { $('<div class="fx-dark"></div>').appendTo('#image-area'); return true; };
sceneEvents.lightsOn = function () { $('#image-area .fx-dark').remove(); return true; };
// a remembered scene: the picture of that night behind the words, then the room again
